const tableFields=['label','category','entity_index','class','name','x','y','z','victim_link','scripts'];
function updateMapInfo(){const b=data.bounds;$('mapInfoBody').innerHTML=`<dl class="fields">${['X','Y','Z'].map(k=>`<dt>${k}</dt><dd>${fmt(b['min'+k])}…${fmt(b['max'+k])}</dd>`).join('')}</dl><button id="openTable">↗ Entity table</button><a class="sourceLink" href="source/${data.key}/annotated_entities.csv" download>↓ Original CSV</a><a class="sourceLink" href="data/${data.key}.json" download>↓ Full data</a><details><summary>Script files</summary>${(data.script_files||[]).map(f=>`<a class="sourceLink" href="${esc(f)}" download>${esc(f.split('/').pop())}</a>`).join('')}</details>`;$('openTable').onclick=()=>{$('tableSearch').value='';buildTable();flightKeys={};flightVelocity=[0,0,0];$('tableDialog').showModal();};}
function buildTable(){const q=$('tableSearch').value.toLowerCase().trim();const rows=data.markers.filter(m=>!q||tableFields.map(k=>m[k]??'').join(' ').toLowerCase().includes(q));$('tableCount').textContent=rows.length+' / '+data.markers.length;$('tableHead').innerHTML=tableFields.map(k=>`<th>${k}</th>`).join('');$('tableBody').innerHTML=rows.map(m=>`<tr>${tableFields.map(k=>`<td>${k==='label'?`<button data-table-pick="${m.id}" style="color:${CAT[m.category][1]}">${esc(m.label)}</button>`:esc(m[k])}</td>`).join('')}</tr>`).join('');}
$('tableSearch').oninput=buildTable;$('closeTable').onclick=()=>$('tableDialog').close();$('tableBody').onclick=e=>{const b=e.target.closest('[data-table-pick]');if(b){$('tableDialog').close();select(b.dataset.tablePick,true);}};

function resetFeatures(){showTargetLinks=false;zoneMarker=null;motionClip=null;motionTime=0;motionPlaying=false;motionTracks=null;motionPending=null;motionPoses=new Map();showVictimModels=false;$('targetLinks').classList.remove('active');$('victimModels').checked=false;$('victimState').textContent='';$('zoneSelect').value='';motionDots.clear();$('animationEnabled').checked=false;if($('scriptDialog').open)$('scriptDialog').close();syncMotion();}
function updateFeatureControls(){const f=data.features;$('zoneSelect').innerHTML='<option value="">Rooms / zones</option>'+f.zones.map(z=>`<option value="${esc(z.marker)}">${esc(z.name)}</option>`).join('');$('zoneSelect').hidden=!f.zones.length;}
function syncMotion(){const on=$('animationEnabled').checked&&!!motionClip;$('animationTime').disabled=!on||!motionTracks;$('animationTime').max=motionClip?.duration||1;$('animationTime').value=motionTime;$('animationValue').textContent=`${fmt(motionTime)} / ${fmt(motionClip?.duration||0)} s`;$('animationPlay').disabled=mode!=='3d'||!on||!motionTracks;$('animationPlay').textContent=motionPlaying?'Ⅱ':'▶';document.querySelectorAll('[data-motion-play]').forEach(b=>{b.disabled=mode!=='3d';b.textContent=motionPlaying&&motionClip?.id===b.dataset.motionPlay?'Ⅱ':'▶';b.setAttribute('aria-pressed',String(motionPlaying&&motionClip?.id===b.dataset.motionPlay));});const check=$('objects').querySelector('[data-motion-all]');if(check){check.checked=motionDots.size===data.features.clips.length;check.indeterminate=motionDots.size>0&&!check.checked;}}
function updateMotion(){motionPoses=$('animationEnabled').checked&&motionTracks?motionStates(motionClip,motionTime,motionTracks):new Map();syncMotion();requestDraw();}
async function ensureMotions(){if(motionTracks||!motionClip)return;if(motionPending)return motionPending;const key=data.key,token=loadToken;const pending=fetch(`data/animations/${key}.json`).then(r=>{if(!r.ok)throw Error('Motion data '+r.status);return r.json();}).then(tracks=>{if(token!==loadToken)return;motionTracks=tracks;updateMotion();}).catch(e=>{if(token===loadToken){$('animationEnabled').checked=false;motionPlaying=false;updateMotion();showError('Motion preview: '+e.message);}}).finally(()=>{if(motionPending===pending)motionPending=null;});motionPending=pending;return pending;}
function focusBounds(b){const center=b.min.map((v,i)=>(v+b.max[i])/2);if(mode==='2d'){scale=Math.min((width-90)/Math.max(b.max[0]-b.min[0],300),(height-120)/Math.max(b.max[2]-b.min[2],300));offsetX=width/2-center[0]*scale;offsetY=(height-50)/2-center[2]*scale;}else{if(flying)setFly(false);controls.target.set(...center);const size=Math.max(...b.max.map((v,i)=>v-b.min[i]),300);camera.position.copy(controls.target).addScaledVector(new THREE.Vector3(.3,.6,.8).normalize(),size*1.65/Math.min(camera.aspect,1));controls.update();}requestDraw();}
function chooseMotion(id){motionPlaying=false;motionTime=0;motionClip=data.features.clips.find(c=>c.id===id)||null;$('animationEnabled').checked=!!motionClip;if(motionClip){motionDots.add(motionClip.id);openGroups.add('MOTION');ensureMotions();}updateMotion();buildList();}
async function playMotion(id,switchMode=false){if(mode!=='3d'){if(!switchMode)return;const oldCamera=camera?.position.clone(),oldTarget=controls?.target.clone(),oldRotation=camera?.quaternion.clone();setMode('3d');if(oldCamera){camera.position.copy(oldCamera);controls.target.copy(oldTarget);camera.quaternion.copy(oldRotation);controls.update();}if(mode!=='3d')return;}if(motionClip?.id===id&&motionPlaying){motionPlaying=false;syncMotion();return;}if(motionClip?.id!==id)chooseMotion(id);if(!motionClip)return;const clip=motionClip,token=loadToken;$('animationEnabled').checked=true;motionDots.add(id);await ensureMotions();if(token!==loadToken||motionClip!==clip||mode!=='3d'||!motionTracks||!motionDots.has(id))return;if(motionTime>=clip.duration)motionTime=0;motionPlaying=true;motionLast=performance.now();updateMotion();buildList();}

function stepMotion(){if(!motionPlaying||!motionClip||!motionTracks||!$('animationEnabled').checked)return;const now=performance.now();motionTime=Math.min(motionClip.duration,motionTime+Math.min((now-motionLast)/1000,.1));motionLast=now;if(motionTime>=motionClip.duration)motionPlaying=false;updateMotion();}
function markerPosition(m){if(mode!=='3d'||!motionPoses.size||!m.models?.length)return m;const positions=m.models.filter(i=>motionPoses.has(i)).map(i=>{const b=data.models[i],p=new THREE.Vector3(...localPoint(b.min.map((v,a)=>(v+b.max[a])/2),i,data)),pose=motionPoses.get(i);return p.applyQuaternion(pose.rotation).add(pose.translation).add(new THREE.Vector3(...b.origin));});if(!positions.length)return m;const p=positions.reduce((s,v)=>s.add(v),new THREE.Vector3()).multiplyScalar(1/positions.length);return {...m,x:p.x,y:p.y,z:p.z};}
async function ensureVictims(){if(!data||!scene||!showVictimModels||victimGroup||victimPending)return;const token=loadToken,pending={};victimPending=pending;$('victimState').textContent='…';try{const group=await buildVictimModels(data);if(token!==loadToken||victimPending!==pending){disposeGroup(group);return;}victimGroup=group;scene.add(group);$('victimState').textContent='';requestDraw();}catch(e){if(token===loadToken){showVictimModels=false;$('victimModels').checked=false;$('victimState').textContent='Unavailable';console.error(e);}}finally{if(victimPending===pending)victimPending=null;}}
function selectedZones(){const z=data.features.zones.find(z=>z.marker===zoneMarker);return (z?.markers||[]).map(id=>data.markers.find(m=>m.id===id)).filter(m=>m?.bounds);}
function drawFeatures(c){for(const clip of data.features.clips.filter(c=>motionDots.has(c.id))){const m=motionMarker(clip),[x,y,on]=project(m);if(!on||x<0||y<0||x>width||y>height)continue;circle(c,x,y,5,'#956bb0',true);c.lineWidth=1.5;circle(c,x,y,7,'#fff');if(motionPlaying&&motionClip?.id===clip.id){c.fillStyle='#fff';c.beginPath();c.moveTo(x-1.5,y-2.5);c.lineTo(x+2,y);c.lineTo(x-1.5,y+2.5);c.closePath();c.fill();}screenMarkers.push({m,x,y});}for(const zone of selectedZones()){const b=zone.bounds,points=[];for(let i=0;i<8;i++)points.push(project({x:b[(i&1)?'max':'min'][0],y:b[(i&2)?'max':'min'][1],z:b[(i&4)?'max':'min'][2]}));c.strokeStyle='#417e9c';c.lineWidth=2;c.setLineDash([6,4]);c.beginPath();for(let i=0;i<8;i++)for(const bit of [1,2,4])if(!(i&bit)&&points[i][2]&&points[i|bit][2]){c.moveTo(points[i][0],points[i][1]);c.lineTo(points[i|bit][0],points[i|bit][1]);}c.stroke();c.setLineDash([]);}
 if(!showTargetLinks)return;const links=data.features.links.filter(l=>!selected||l.from===selected||l.to===selected);const endpoints=new Set();for(const link of links){const a=data.markers.find(m=>m.id===link.from),b=data.markers.find(m=>m.id===link.to);if(!a||!b)continue;if(!selected&&!visible(a))continue;const [x,y,on]=project(a),[tx,ty,ton]=project(b);if(!on||!ton)continue;const angle=Math.atan2(ty-y,tx-x);c.strokeStyle='#867045aa';c.fillStyle='#867045';c.lineWidth=1.3;c.beginPath();c.moveTo(x,y);c.lineTo(tx,ty);c.stroke();c.beginPath();c.moveTo(tx,ty);c.lineTo(tx-9*Math.cos(angle-.45),ty-9*Math.sin(angle-.45));c.lineTo(tx-9*Math.cos(angle+.45),ty-9*Math.sin(angle+.45));c.closePath();c.fill();for(const m of [a,b])if(!visible(m)&&!endpoints.has(m.id)){endpoints.add(m.id);const [px,py]=project(m);circle(c,px,py,4,'#867045',true);c.font='10px ui-monospace,monospace';c.fillText(m.label,px+7,py-5);screenMarkers.push({m,x:px,y:py});}}
}
function scriptTable(rows){return `<table class="meaningTable"><thead><tr><th>Command / condition</th><th>Meaning</th></tr></thead><tbody>${rows.map(r=>`<tr><td><code title="${esc(r.meaning)}">${esc(r.code)}</code></td><td>${esc(r.meaning)}</td></tr>`).join('')}</tbody></table>`;}
function macroSummary(name){const body=macroText(data.features.macros,name);return scriptRows(expandScript(body||'',data.features.macros)).slice(0,3).map(r=>r.meaning).join(' ')||meaning(name);}
function openScript(name,entity){const raw=entity?entity.script_lines.join('\n'):macroText(data.features.macros,name),expanded=entity?entity.expanded_scripts:expandScript(raw||'',data.features.macros);$('scriptTitle').textContent=entity?entity.label+' · '+entity.name:name;const rows=scriptRows(expanded||'');$('scriptBody').innerHTML=(rows.length?scriptTable(rows):'<p>No decoded commands in this definition.</p>')+`<details><summary>Authored definition</summary><pre class="script">${esc(raw||'No definition found in the copied scripts.')}</pre></details><details><summary>Expanded script</summary><pre class="script">${esc(expanded||'')}</pre></details><p class="explain">Conditions apply to their own branches. This describes the authored commands; it does not evaluate a live stage state.</p>`;flightKeys={};flightVelocity=[0,0,0];motionPlaying=false;syncMotion();$('scriptDialog').showModal();}
function initFeatureHandlers(){$('targetLinks').onclick=()=>{showTargetLinks=!showTargetLinks;$('targetLinks').classList.toggle('active',showTargetLinks);requestDraw();};$('zoneSelect').onchange=e=>{zoneMarker=e.target.value||null;const ms=selectedZones();if(ms.length)focusBounds({min:[0,1,2].map(a=>Math.min(...ms.map(m=>m.bounds.min[a]))),max:[0,1,2].map(a=>Math.max(...ms.map(m=>m.bounds.max[a])))});requestDraw();};$('animationEnabled').onchange=e=>{if(e.target.checked&&!motionClip){chooseMotion(data.features.clips[0]?.id);return;}motionPlaying=false;if(e.target.checked){motionDots.add(motionClip.id);ensureMotions();}else motionTime=0;updateMotion();};$('animationTime').oninput=e=>{motionPlaying=false;motionTime=Number(e.target.value);updateMotion();};$('animationPlay').onclick=()=>{if(motionClip)playMotion(motionClip.id);};$('animationReset').onclick=()=>{motionPlaying=false;motionTime=0;updateMotion();};$('victimModels').onchange=e=>{showVictimModels=e.target.checked;if(showVictimModels)ensureVictims();requestDraw();};$('closeScript').onclick=()=>$('scriptDialog').close();document.addEventListener('visibilitychange',()=>{if(document.hidden){motionPlaying=false;syncMotion();}});}
function motionLegend(){const clips=data.features.clips.filter(c=>!query||[c.name,c.id,'motion'].join(' ').toLowerCase().includes(query));if(!clips.length)return '';return `<details class="keyGroup" data-group="MOTION" ${openGroups.has('MOTION')||query?'open':''}><summary><span class="dot" style="background:#956bb0"></span>Motion<small>${clips.length}</small><input type="checkbox" data-motion-all aria-label="Show all motion markers"></summary>${clips.map(c=>`<div class="object motionObject"><input type="checkbox" data-motion-dot="${esc(c.id)}" aria-label="Show ${esc(c.name)} motion dot" ${motionDots.has(c.id)?'checked':''}><button class="pick" data-motion-pick="${esc(c.id)}" title="Select motion · preserves camera"><b class="motionDot" style="color:#956bb0">●</b><span class="name">${esc(c.name)}</span></button><button class="motionPlay" data-motion-play="${esc(c.id)}" aria-label="Play ${esc(c.name)}" title="${mode==='3d'?'Play / pause · preserves camera':'Switch to 3D to play'}" ${mode==='3d'?'':'disabled'}>▶</button></div>${motionClip?.id===c.id?'<div data-motion-controls></div>':''}`).join('')}</details>`;}
function motionMarker(clip){const controller=data.markers.find(m=>m.id===clip.id),models=clip.parts.map(p=>data.models[p.model]),center=[0,1,2].map(a=>(Math.min(...models.map(m=>m.min[a]))+Math.max(...models.map(m=>m.max[a])))/2);return {...controller,id:'motion:'+clip.id,motionId:clip.id,name:clip.name,label:controller?.label||'Motion',class:'Motion preview',category:'MOTION',x:center[0],y:center[1],z:center[2],models:clip.parts.map(p=>p.model),script_lines:controller?.script_lines||[],raw:controller?.raw||{}};}

function scriptCards(rows){return `<div class="scriptCards">${rows.map(r=>`<div class="scriptCard ${r.condition?'condition':'action'}"><code title="${esc(r.meaning)}">${esc(r.code)}</code><p>${esc(r.meaning)}</p></div>`).join('')}</div>`;}
